solution.solution.cpp:
struct Width
{
    explicit Width(double v) : value{ v } {}
    double value{};
};

struct Height
{
    explicit Height(double v) : value{ v } {}
    double value{};
};

class Rectangle
{
public:
    Rectangle(Width width, Height height) : m_width{ width.value }, m_height{ height.value } {}
    double area() const { return m_width * m_height; }

private:
    double m_width{};
    double m_height{};
};

unitTests:
static_assert(std::is_constructible_v<Rectangle, Width, Height>, "Rectangle{ Width{...}, Height{...} } should compile");
static_assert(!std::is_constructible_v<Rectangle, double, double>, "Rectangle{ 10, 20 } should NOT compile: make the Width and Height constructors explicit");
static_assert(!std::is_constructible_v<Rectangle, Height, Width>, "the arguments must not be swappable");

TEST("area") { const Rectangle r{ Width{ 10 }, Height{ 20 } }; CHECK_NEAR(r.area(), 200.0, 1e-9); }

